/* Imagens locais: base íntegra e variantes de produção registradas em IDENTIDADE.md. */
(()=>{
const pal={papel:'#F4EBDD',tinta:'#1A1D22',ultramarino:'#302ED4',vermelhao:'#F24D3F',menta:'#98D7C7'};
const labels={neutro:'Neutro',cansado:'Cansado',confiante:'Confiante',desconfiado:'Desconfiado',constrangido:'Constrangido',panico:'Pânico',aliviado:'Aliviado',ironia:'Ironia'};
const choice=(id,label)=>({id,label});
const bases=['a','b','c'].map((id,i)=>({id,label:['Base A · tranças','Base B · óculos','Base C · cachos'][i],portrait:'assets/rostos/base-'+id+'.webp',expressions:Object.fromEntries(Object.keys(labels).map(k=>[k,'assets/rostos/'+id+'-'+k+'.webp']))}));
const faces=[choice('original','Contorno da base'),choice('a','Alongado'),choice('b','Largo'),choice('c','Maçãs salientes')];
const skins=[choice('original','Tom da ilustração'),choice('dourada','Dourado quente'),choice('retinta','Marrom profundo')];
const hairs=[choice('original','Cabelo da ilustração'),choice('castanho','Acobreado'),choice('mecha','Mecha caramelo')];
const outfits=[choice('original','Roupa da ilustração'),choice('colete','Ultramarino'),choice('jaqueta','Verde-menta')];
const expressions=Object.entries(labels).map(([id,label])=>choice(id,label));
/* A imagem composta usa BMP sem dependências do navegador, fontes ou rede.
 * As matrizes de contorno são geradas por coordenadas locais; as máscaras só
 * afetam as áreas de pele, cabelo e vestuário do próprio retrato.
 */
const sheets={"a-neutro":["","",""],"a-cansado":["","",""],"a-confiante":["","",""],"a-desconfiado":["","",""],"a-constrangido":["","",""],"a-panico":["","",""],"a-aliviado":["","",""],"a-ironia":["","",""],"b-neutro":["","",""],"b-cansado":["","",""],"b-confiante":["","",""],"b-desconfiado":["","",""],"b-constrangido":["","",""],"b-panico":["","",""],"b-aliviado":["","",""],"b-ironia":["","",""],"c-neutro":["","",""],"c-cansado":["","",""],"c-confiante":["","",""],"c-desconfiado":["","",""],"c-constrangido":["","",""],"c-panico":["","",""],"c-aliviado":["","",""],"c-ironia":["","",""]};
const decoded=new Map(),cache=new Map();
const clamp=(x,a,b)=>Math.min(b,Math.max(a,x));
const decode=s=>Uint8Array.from(atob(s),c=>c.charCodeAt(0));
function unpack(key){
 if(decoded.has(key))return decoded.get(key);
 const [palette,indices,encodedMasks]=sheets[key],mask=new Uint8Array(320*320),runs=decode(encodedMasks);
 for(let i=0,j=0;i<runs.length;i+=2){mask.fill(runs[i+1],j,j+runs[i]);j+=runs[i]}
 const data={colors:decode(palette),pixels:decode(indices),mask};decoded.set(key,data);return data;
}
function render(p={}){
 const base=bases.find(b=>b.id===p.base)||bases[0],face=faces.find(o=>o.id===p.face)?.id||'original';
 const key=Object.hasOwn(labels,p.expression)?p.expression:'neutro';
 const skin=skins.find(o=>o.id===p.skin)?.id||'original',hair=hairs.find(o=>o.id===p.hair)?.id||'original',outfit=outfits.find(o=>o.id===p.outfit)?.id||'original';
 if([face,skin,hair,outfit].every(v=>v==='original'))return base.expressions[key];
 const cacheKey=[base.id,key,face,skin,hair,outfit].join('_');if(cache.has(cacheKey))return cache.get(cacheKey);
 const {colors,pixels,mask}=unpack(base.id+'-'+key);
 const size=320,stride=3*size,bytes=new Uint8Array(54+size*stride),dv=new DataView(bytes.buffer);
 bytes[0]=66;bytes[1]=77;dv.setUint32(2,bytes.length,true);dv.setUint32(10,54,true);dv.setUint32(14,40,true);
 dv.setInt32(18,size,true);dv.setInt32(22,-size,true);dv.setUint16(26,1,true);dv.setUint16(28,24,true);dv.setUint32(34,size*stride,true);
 const skinTarget=skin==='dourada'?[220,150,103]:[132,77,52],skinLuma={a:121,b:173,c:162}[base.id];
 const garmentTarget=outfit==='colete'?[69,66,190]:[109,181,163],clothLuma={a:119,b:179,c:154}[base.id];
 const center={a:[.55,.53],b:[.56,.44],c:[.51,.47]}[base.id],shape={a:[.18,-.19,0],b:[-.23,.14,.03],c:[-.20,.05,-.08]}[face];
 const colorCache=new Map();
 for(let y=0,j=54;y<size;y++){for(let x=0;x<size;x++){
  let ix=x,iy=y;
  if(shape){
   const xx=((x+.5)/size-center[0])/.27,yy=((y+.5)/size-center[1])/.27,fall=Math.exp(-(xx*xx*1.3+(yy-shape[2])**2*1.5));
   ix=clamp(Math.round(x+38*shape[0]*xx*fall*3.4),0,size-1);iy=clamp(Math.round(y+38*shape[1]*yy*fall*2.8),0,size-1);
  }
  const k=iy*size+ix,pix=pixels[k],marks=mask[k],tag=pix*256+marks;
  let rgb=colorCache.get(tag);
  if(!rgb){
   const q=pix*3,r=colors[q],g=colors[q+1],b=colors[q+2],lum=.299*r+.587*g+.114*b;
   rgb=[r,g,b];const mix=(target,alpha)=>{if(alpha>0)for(let c=0;c<3;c++)rgb[c]+=alpha*(clamp(target[c],0,255)-rgb[c])};
   if(skin!=='original'){const t=(Math.max(12,lum)/skinLuma)**.88;mix(skinTarget.map(c=>c*t),(marks&3)/3*(skin==='dourada'?.87:.94))}
   if(hair==='castanho')mix([r*1.36+10,g*1.08+3,b*.96],(marks>>2&3)/3);
   if(hair==='mecha')mix([r*1.68+16,g*1.32+8,b*1.10+2],(marks>>4&3)/3);
   if(outfit!=='original'){const t=clamp(lum/clothLuma,.14,1.25);mix(garmentTarget.map(c=>c*t),(marks>>6&3)/3)}
   colorCache.set(tag,rgb);
  }
  bytes[j++]=rgb[2];bytes[j++]=rgb[1];bytes[j++]=rgb[0];
 }}
 let bin='';for(let i=0;i<bytes.length;i+=8192)bin+=String.fromCharCode(...bytes.subarray(i,i+8192));
 const url='data:image/bmp;base64,'+btoa(bin);
 if(cache.size>=32)cache.delete(cache.keys().next().value);cache.set(cacheKey,url);return url;
}
window.FVQE_VISUAL={palette:pal,bases,faces,skins,hairs,outfits,expressions,expressionLabels:labels,render};
})();
